head.b:skin:
/* =====================================================
   NCERT SANGRAM v0.1
   Production Theme
===================================================== */

:root{

--primary:#1565C0;
--primary-dark:#0D47A1;
--accent:#FFC107;

--white:#ffffff;
--black:#222222;

--bg:#F5F7FA;

--card:#ffffff;

--border:#E5E7EB;

--radius:16px;

--shadow:0 8px 25px rgba(0,0,0,.08);

}

/* RESET */

*{

margin:0;

padding:0;

box-sizing:border-box;

}

html{

scroll-behavior:smooth;

}

body{

background:var(--bg);

font-family:'Poppins',sans-serif;

font-size:16px;

color:var(--black);

line-height:1.7;

}

img{

display:block;

max-width:100%;

height:auto;

}

a{

text-decoration:none;

color:inherit;

}

ul{

list-style:none;

}

.container{

width:94%;

max-width:1280px;

margin:auto;

}

/* HEADER */

.header{

position:sticky;

top:0;

background:var(--primary);

box-shadow:var(--shadow);

z-index:999;

}

.header-inner{

display:flex;

justify-content:space-between;

align-items:center;

padding:18px 0;

}

.logo{

font-size:30px;

font-weight:700;

color:#fff;

}

.menu{

display:flex;

gap:28px;

align-items:center;

}

.menu a{

color:#fff;

font-weight:600;

transition:.25s;

}

.menu a:hover{

opacity:.8;

}

/* HERO */

.hero{

padding:90px 20px;

background:#fff;

text-align:center;

}

.hero h1{

font-size:52px;

font-weight:700;

color:var(--primary);

}

.hero p{

margin-top:20px;

font-size:20px;

}

.btn{

display:inline-block;

margin-top:30px;

padding:15px 36px;

border-radius:12px;

font-weight:600;

background:var(--primary);

color:#fff;

}

.btn.secondary{

background:var(--accent);

color:#000;

margin-left:12px;

}

/* SEARCH */

.search{

margin:45px auto;

}

.search input{

width:100%;

padding:18px;

font-size:17px;

border:1px solid var(--border);

border-radius:12px;

}

/* ADS */

.ads{

margin:35px auto;

background:#fff;

border:2px dashed #ccc;

padding:25px;

text-align:center;

}

/* MOBILE */

@media(max-width:768px){

.header-inner{

flex-direction:column;

}

.menu{

flex-wrap:wrap;

justify-content:center;

gap:16px;

}

.hero h1{

font-size:36px;

}

.hero p{

font-size:17px;

}

}
